require "test_helper"

class TmpBurstEdgeTest < ActiveSupport::TestCase
  setup do
    Current.session = sessions(:david)
    @card = cards(:buy_domain)
  end

  test "burst window follows board entropy override" do
    @card.board.update! auto_postpone_period: 3.days

    travel_to 2.days.ago do
      @card.comments.create! creator: users(:david), body: "One"
    end
    travel_to Time.current do
      @card.comments.create! creator: users(:jz), body: "Two"
      @card.comments.create! creator: users(:david), body: "Three"
    end

    assert_nil @card.reload.last_burst_at
  end

  test "burst window falls back to account entropy" do
    @card.board.entropy.destroy!
    @card.board.reload
    @card.account.entropy.update! auto_postpone_period: 3.days

    @card.comments.create! creator: users(:david), body: "One"
    @card.comments.create! creator: users(:jz), body: "Two"
    @card.comments.create! creator: users(:david), body: "Three"

    assert @card.reload.last_burst_at.present?
  end

  test "two comments do not burst" do
    @card.comments.create! creator: users(:david), body: "One"
    @card.comments.create! creator: users(:jz), body: "Two"

    assert_nil @card.reload.last_burst_at
  end

  test "system comments do not count" do
    @card.comments.create! creator: users(:david), body: "One"
    @card.comments.create! creator: users(:jz), body: "Two"
    @card.comments.create! creator: users(:system), body: "Three"

    assert_nil @card.reload.last_burst_at
  end

  test "unassigning does not burst" do
    @card.toggle_assignment users(:david)
    @card.update! last_burst_at: nil, burst_at: nil, burst: false

    @card.toggle_assignment users(:david)

    assert_nil @card.reload.last_burst_at
  end

  test "closing does not burst" do
    @card.close

    assert_nil @card.reload.last_burst_at
  end
end
EOF
