import { Controller } from "@hotwired/stimulus"
import { signedDifferenceInDays } from "helpers/date_helpers"

const REFRESH_INTERVAL = 3_600_000 // 1 hour (in milliseconds)
const STALLED_AFTER_IN_DAYS = 14

export default class extends Controller {
  static targets = [ "entropy", "top", "center", "bottom" ]
  static values = { entropy: Object }

  #timer

  connect() {
    this.#timer = setInterval(this.update.bind(this), REFRESH_INTERVAL)
    this.update()
  }

  disconnect() {
    clearInterval(this.#timer)
  }

  update() {
    if (this.#isStalled) {
      this.#showStalled()
    } else if (this.#hasEntropy) {
      this.#showEntropy()
    } else {
      this.#hide()
    }
  }

  get #isStalled() {
    if (this.#hasBurst && this.entropyValue.lastActiveAt) {
      return this.#stalledInDays >= STALLED_AFTER_IN_DAYS
    }

    return this.entropyValue.stalled === true || Number.isFinite(this.entropyValue.stalledDays)
  }

  get #hasBurst() {
    return Boolean(this.entropyValue.lastBurstAt || this.entropyValue.burstAt)
  }

  get #stalledInDays() {
    const lastActiveAt = this.entropyValue.lastActiveAt
    if (lastActiveAt) {
      return signedDifferenceInDays(new Date(lastActiveAt), new Date())
    }

    if (Number.isFinite(this.entropyValue.stalledDays)) {
      return this.entropyValue.stalledDays
    }

    return this.entropyValue.stalledAt ? signedDifferenceInDays(new Date(this.entropyValue.stalledAt), new Date()) : 0
  }

  get #hasEntropy() {
    return this.#entropyCleanupInDays < this.entropyValue.daysBeforeReminder
  }

  get #entropyCleanupInDays() {
    return signedDifferenceInDays(new Date(), new Date(this.entropyValue.closesAt))
  }

  #showEntropy() {
    this.#render({
      top: this.#entropyCleanupInDays < 1 ? this.entropyValue.action : `${this.entropyValue.action} in`,
      center: this.#entropyCleanupInDays < 1 ? "!" : this.#entropyCleanupInDays,
      bottom: this.#entropyCleanupInDays < 1 ? "Today" : (this.#entropyCleanupInDays === 1 ? "day" : "days"),
    })
  }

  #render({ top, center, bottom }) {
    this.topTarget.innerHTML = top
    this.centerTarget.innerHTML = center
    this.bottomTarget.innerHTML = bottom

    this.#show()
  }

  #showStalled() {
    const days = this.#stalledInDays

    this.#render({
      top: "Stalled for",
      center: days,
      bottom: days === 1 ? "day" : "days"
    })
  }

  #hide() {
    this.element.toggleAttribute("hidden", true)
  }

  #show() {
    this.element.removeAttribute("hidden")
  }
}

